```go
package main

import (
    "fmt"
    "sync"
)

func main() {
    var mu sync.Mutex
    var wg sync.WaitGroup
    total := 0

    for range 4 {
        wg.Add(1)
        go func() {
            defer wg.Done()
            mu.Lock()
            total += 25
            mu.Unlock()
        }()
    }

    wg.Wait()
    fmt.Println(total)
}
```
The mutex protects the shared update; the WaitGroup protects the lifecycle of the final read. The output is always `100`.

```go
package main

import (
    "fmt"
    "sync"
)

func main() {
    jobs := make(chan int)
    results := make(chan int)
    var workers sync.WaitGroup

    for range 2 {
        workers.Add(1)
        go func() {
            defer workers.Done()
            for job := range jobs { results <- job * job }
        }()
    }
    go func() {
        for _, job := range []int{1, 2, 3, 4} { jobs <- job }
        close(jobs)
    }()
    go func() { workers.Wait(); close(results) }()

    total := 0
    for result := range results { total += result }
    fmt.Println(total)
}
```
The close order is jobs, workers, then results. Scheduling may vary, but the total is always `30`.
